    private data class GlyphPath(
        val data: String,
        val fill: Boolean,
        val stroke: Boolean,
        val evenOdd: Boolean,
        val strokeWidth: Float,
    )

    private fun buildGlyph(
        name: String,
        defaultWidth: Float,
        defaultHeight: Float,
        viewportWidth: Float,
        viewportHeight: Float,
        paths: List<GlyphPath>,
    ): ImageVector = ImageVector.Builder(
        name = name,
        defaultWidth = defaultWidth.dp,
        defaultHeight = defaultHeight.dp,
        viewportWidth = viewportWidth,
        viewportHeight = viewportHeight,
    ).apply {
        paths.forEach { path ->
            addPath(
                pathData = PathParser().parsePathString(path.data).toNodes(),
                pathFillType = if (path.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = if (path.fill) SolidColor(Color.Black) else null,
                stroke = if (path.stroke) SolidColor(Color.Black) else null,
                strokeLineWidth = path.strokeWidth,
            )
        }
    }.build()
